// Delivery charge for a checkout.
//
// The charge is a single figure for the WHOLE checkout, even though a
// multi-farmer cart is placed as one order batch per farmer:
//
//     delivery = farmers === 0 ? 0 : base + extra × (farmers - 1)
//
// `base` covers the rider's trip (and the first farmer's pickup); every
// additional farmer is another pickup stop, so it adds `extra`. Both figures
// are moderator-set (platform_settings.delivery_base_fee / delivery_extra_fee)
// and default to ₹30 / ₹15. The resolved rupees are stamped on orders.delivery_fee
// at placement (see src/app/api/orders/place/route.ts): `base` on the first
// farmer's batch, `extra` on each subsequent farmer's batch, so the stamped
// fees across a checkout always sum to the formula above.
//
// Refunds (farmer decline / buyer cancel) recompute how many farmers remain in
// the checkout and give back the drop — see planDeliveryRefund below.

import type { SupabaseClient } from '@supabase/supabase-js'

// Sensible ceiling for the moderator inputs — a guard against a fat-fingered
// entry, not a business rule.
export const DELIVERY_FEE_MAX = 1000

// Launch defaults, also used as the fallback when the settings row/columns
// aren't migrated yet so checkout is never blocked.
export const DEFAULT_DELIVERY_BASE_FEE = 30
export const DEFAULT_DELIVERY_EXTRA_FEE = 15

export type DeliveryCharges = { base: number; extra: number }

// Total delivery charge for a checkout with `farmerCount` participating farmers.
export function computeDeliveryTotal(farmerCount: number, { base, extra }: DeliveryCharges): number {
  if (!Number.isFinite(farmerCount) || farmerCount <= 0) return 0
  const b = Math.max(0, Math.round(base))
  const e = Math.max(0, Math.round(extra))
  return b + e * (farmerCount - 1)
}

// Read the current base + extra charges. Best-effort: if the table/columns
// don't exist yet (migration not applied) or anything fails, fall back to the
// launch defaults so checkout and refunds are never blocked.
export async function getDeliveryCharges(supabase: SupabaseClient): Promise<DeliveryCharges> {
  try {
    const { data, error } = await supabase
      .from('platform_settings')
      .select('delivery_base_fee, delivery_extra_fee')
      .eq('id', 1)
      .maybeSingle()
    if (error) return { base: DEFAULT_DELIVERY_BASE_FEE, extra: DEFAULT_DELIVERY_EXTRA_FEE }
    const base = Number(data?.delivery_base_fee)
    const extra = Number(data?.delivery_extra_fee)
    return {
      base: Number.isFinite(base) && base >= 0 ? base : DEFAULT_DELIVERY_BASE_FEE,
      extra: Number.isFinite(extra) && extra >= 0 ? extra : DEFAULT_DELIVERY_EXTRA_FEE,
    }
  } catch {
    return { base: DEFAULT_DELIVERY_BASE_FEE, extra: DEFAULT_DELIVERY_EXTRA_FEE }
  }
}

// ── Refunds ──────────────────────────────────────────────────────────────
//
// planDeliveryRefund works out how much delivery charge to give back when one
// order in a checkout is declined/cancelled, and which orders' payments to pull
// it from. It is a pure function so the farmer-decline and buyer-cancel routes
// share exactly one implementation and can't drift.

// A status that means the order is no longer part of the delivery run.
const GONE = new Set(['declined', 'cancelled'])

// The minimum shape planDeliveryRefund needs from each sibling order row.
export type RefundOrderRow = {
  id: string
  farmer_id: string | null
  status: string | null
  delivery_fee: number | null
  delivery_fee_refunded: number | null
  payment_status: string | null
  razorpay_payment_id: string | null
}

// One refund to issue against one order's payment.
export type DeliveryRefundAllocation = {
  orderId: string
  // Rupees to refund from THIS order's captured payment.
  amount: number
  // How much of this row's delivery_fee will have been refunded after this
  // allocation (row.delivery_fee_refunded + amount) — write straight back.
  newRefundedTotal: number
  razorpayPaymentId: string | null
  // true → issue a real Razorpay refund; false → a non-Razorpay captured
  // payment, so the caller flags it for manual settlement instead.
  viaRazorpay: boolean
}

export type DeliveryRefundPlan = {
  // Total delivery rupees to refund across all allocations.
  owed: number
  allocations: DeliveryRefundAllocation[]
}

function participating(row: RefundOrderRow): boolean {
  return !GONE.has(String(row.status ?? ''))
}

// Was money actually captured for this row (so a delivery refund is possible)?
function captured(row: RefundOrderRow): { yes: boolean; viaRazorpay: boolean } {
  const s = String(row.payment_status ?? '')
  const viaRazorpay = (s === 'paid' || s === 'deposit_paid') && !!row.razorpay_payment_id
  const otherPaid = s === 'completed' || s === 'payment_claimed' || s === 'pending_confirmation'
  return { yes: viaRazorpay || otherPaid, viaRazorpay }
}

function refundableDelivery(row: RefundOrderRow): number {
  return Math.max(0, (Number(row.delivery_fee) || 0) - (Number(row.delivery_fee_refunded) || 0))
}

/**
 * Plan the delivery-charge refund for cancelling one order out of a checkout.
 *
 * @param siblings  every order row sharing the checkout_id (including the one
 *                  being cancelled), each still carrying its CURRENT status —
 *                  i.e. call this BEFORE writing the declined/cancelled status.
 * @param cancelId  the order id being declined/cancelled.
 * @param charges   the current base/extra (from getDeliveryCharges).
 *
 * Returns the rupees to give back and the per-order allocations. Item price and
 * platform fee are handled by the caller; this covers only delivery.
 */
export function planDeliveryRefund(
  siblings: RefundOrderRow[],
  cancelId: string,
  { base, extra }: DeliveryCharges,
): DeliveryRefundPlan {
  const target = siblings.find((r) => r.id === cancelId)
  if (!target) return { owed: 0, allocations: [] }

  // Farmers with at least one live order, before vs after this cancellation.
  const farmersOf = (rows: RefundOrderRow[]) =>
    new Set(rows.filter(participating).map((r) => String(r.farmer_id ?? '')))
  const before = farmersOf(siblings).size
  const after = farmersOf(siblings.filter((r) => r.id !== cancelId)).size

  // Delivery money still held (stamped but not yet refunded) across the whole
  // checkout — includes residual left on already-cancelled base rows.
  const remainingHeld = siblings.reduce((s, r) => s + refundableDelivery(r), 0)

  // How much the delivery charge drops.
  //   - farmer still has other live orders (before === after) → no drop (Case 5)
  //   - last farmer leaving → refund everything still held (base included)
  //   - a non-last farmer leaving → refund one `extra` unit
  let owed: number
  if (after === before) owed = 0
  else if (after === 0) owed = remainingHeld
  else owed = Math.min(Math.max(0, Math.round(extra)), remainingHeld)

  // Only rows whose payment was captured can actually be refunded; never plan
  // to give back more than was collected.
  const candidates = siblings
    .map((r) => ({ row: r, cap: captured(r), refundable: refundableDelivery(r) }))
    .filter((c) => c.cap.yes && c.refundable > 0)
    // Pull from the cancelled order first, then its siblings.
    .sort((a, b) => (a.row.id === cancelId ? -1 : b.row.id === cancelId ? 1 : 0))
  const allocatable = candidates.reduce((s, c) => s + c.refundable, 0)
  owed = Math.min(owed, allocatable)

  const allocations: DeliveryRefundAllocation[] = []
  let left = owed
  for (const c of candidates) {
    if (left <= 0) break
    const amount = Math.min(left, c.refundable)
    if (amount <= 0) continue
    allocations.push({
      orderId: c.row.id,
      amount,
      newRefundedTotal: (Number(c.row.delivery_fee_refunded) || 0) + amount,
      razorpayPaymentId: c.row.razorpay_payment_id,
      viaRazorpay: c.cap.viaRazorpay,
    })
    left -= amount
  }

  return { owed, allocations }
}

// Server-side execution of a delivery-charge refund plan.
//
// When one order in a multi-farmer checkout is declined/cancelled, the delivery
// charge for the WHOLE checkout drops (see planDeliveryRefund in delivery-fee.ts).
// The drop is refunded from one or more orders' captured payments. The order
// being cancelled is refunded by the calling route (folded into its single
// item+platform+delivery refund); this helper issues the refunds that land on
// the OTHER (sibling) orders' payments — e.g. the residual base still sitting on
// an already-cancelled base row when the last farmer finally leaves.

import type { SupabaseClient } from '@supabase/supabase-js'
import { refundPayment } from '@/lib/razorpay'
import type { DeliveryRefundPlan, DeliveryRefundAllocation } from '@/lib/delivery-fee'

// Columns planDeliveryRefund needs from each sibling order row.
export const REFUND_ORDER_COLS =
  'id, farmer_id, status, delivery_fee, delivery_fee_refunded, payment_status, razorpay_payment_id, order_code'

/**
 * Apply the sibling parts of a delivery refund plan (every allocation EXCEPT the
 * order the caller is itself refunding). Best-effort: a gateway failure on one
 * sibling is logged and skipped so the primary decline/cancel still completes.
 *
 * @returns the current order's own allocation, so the caller can fold it into
 *          that order's single refund (amount to add + the new delivery_fee_refunded
 *          value to stamp on it). Zeroes when the plan gives the current order nothing.
 */
export async function applySiblingDeliveryRefunds(
  supabase: SupabaseClient,
  plan: DeliveryRefundPlan,
  currentOrderId: string,
): Promise<{ currentAmount: number; currentRefundedTotal: number | null }> {
  let currentAmount = 0
  let currentRefundedTotal: number | null = null

  for (const alloc of plan.allocations) {
    if (alloc.orderId === currentOrderId) {
      currentAmount = alloc.amount
      currentRefundedTotal = alloc.newRefundedTotal
      continue
    }
    await refundSibling(supabase, alloc)
  }

  return { currentAmount, currentRefundedTotal }
}

async function refundSibling(supabase: SupabaseClient, alloc: DeliveryRefundAllocation): Promise<void> {
  if (alloc.amount <= 0) return

  const rowUpdate: Record<string, unknown> = {
    delivery_fee_refunded: alloc.newRefundedTotal,
    refunded_at: new Date().toISOString(),
  }

  if (alloc.viaRazorpay && alloc.razorpayPaymentId) {
    try {
      await refundPayment({
        paymentId: alloc.razorpayPaymentId,
        amountPaise: Math.round(alloc.amount * 100),
        notes: { reason: 'delivery_charge_adjustment', order_id: alloc.orderId },
      })
    } catch (e) {
      // Don't fail the whole decline/cancel over a secondary sibling refund;
      // record nothing on the row so a later run can retry, and log it.
      console.error('[YFF] sibling delivery refund failed:', alloc.orderId, e)
      return
    }
  } else {
    // Non-Razorpay captured payment — flag for manual settlement.
    rowUpdate.refund_status = 'initiated'
  }

  const { error } = await supabase.from('orders').update(rowUpdate).eq('id', alloc.orderId)
  if (error) console.error('[YFF] sibling delivery_fee_refunded stamp failed:', alloc.orderId, error.message)
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'
import { refundPayment } from '@/lib/razorpay'
import { isDepositPaid } from '@/lib/payment'
import { getDeliveryCharges, planDeliveryRefund, type RefundOrderRow } from '@/lib/delivery-fee'
import { applySiblingDeliveryRefunds, REFUND_ORDER_COLS } from '@/lib/delivery-refund'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

// Buyer cancels their own order. Allowed any time UP TO the point the order is
// shipped or handed over — i.e. while still pending OR approved-and-awaiting.
// There is no time window; only the order's progress decides. Returns the stock
// and, for a paid order, issues a real Razorpay refund — same machinery as a
// farmer decline, but initiated by the buyer.
export async function POST(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Please log in.' }, { status: 401 })

  const { id } = await ctx.params
  if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  // Optional reason the buyer gave for cancelling.
  const body = await req.json().catch(() => null)
  const reason = String((body as { reason?: unknown } | null)?.reason ?? '').trim().slice(0, 300)

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: order, error: loadErr } = await supabase
    .from('orders')
    .select('id, consumer_id, farmer_id, status, quantity, total_price, platform_fee, delivery_fee, delivery_fee_refunded, cod_deposit, produce_listing_id, harvest_id, payment_status, razorpay_payment_id, checkout_id, created_at, order_code, shipped_at, collected_at, received_at, delivery_status')
    .eq('id', id)
    .maybeSingle()

  if (loadErr) return NextResponse.json({ error: loadErr.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.consumer_id !== session.consumerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }
  // Cancellable while still pending or approved-and-awaiting. Blocked once the
  // order is shipped (farmer shipped it, or a rider has picked it up and is in
  // transit) or resolved (picked up / delivered / received), and of course once
  // it's already declined / cancelled.
  const cancellable =
    (order.status === 'pending' || order.status === 'approved')
    && !order.shipped_at
    && !order.collected_at
    && !order.received_at
    && order.delivery_status !== 'picked_up'
    && order.delivery_status !== 'out_for_delivery'
    && order.delivery_status !== 'delivered'
  if (!cancellable) {
    return NextResponse.json(
      { error: 'This order can no longer be cancelled — it has already been shipped or completed.' },
      { status: 409 },
    )
  }

  // Return the reserved stock. Harvest orders return the harvest's stock;
  // legacy orders the listing's.
  if (order.quantity != null && order.quantity > 0) {
    try {
      if (order.harvest_id) {
        await supabase.rpc('increment_harvest_stock', { p_harvest_id: order.harvest_id, p_qty: order.quantity })
      } else if (order.produce_listing_id) {
        await supabase.rpc('increment_stock', { p_listing_id: order.produce_listing_id, p_qty: order.quantity })
      }
    } catch (e) {
      console.error('[YFF] restock on cancel failed:', e)
    }
  }

  const update: Record<string, unknown> = {
    status: 'cancelled',
    decline_reason: reason || 'Cancelled by buyer',
  }

  const paidByRazorpay = order.payment_status === 'paid' && !!order.razorpay_payment_id
  const paidByOther =
    order.payment_status === 'completed' ||
    order.payment_status === 'payment_claimed' ||
    order.payment_status === 'pending_confirmation'

  // Cancellation is the buyer's choice, so the platform fee (moderator
  // commission) is NOT refunded — it covers the gateway/software cost already
  // incurred. We refund the produce price only; the fee stamped on this row
  // (the cart's first row carries it) is withheld. Surfaced to the buyer so the
  // deduction is shown clearly.
  const platformFeeWithheld = Math.max(0, Number(order.platform_fee) || 0)
  const produceRefund = Math.max(0, Number(order.total_price) || 0)

  // The delivery charge, unlike the platform fee, is for a service not rendered,
  // so it IS refunded on a buyer cancel — by the SAME whole-checkout rule as a
  // farmer decline: the charge falls by one farmer's worth (or the residual base
  // when the last farmer leaves), possibly spread across sibling orders. Pure
  // here (no writes); skipped for the deposit path (delivery there was cash).
  let deliveryPlan: ReturnType<typeof planDeliveryRefund> = { owed: 0, allocations: [] }
  let currentDeliveryAmount = 0
  let currentDeliveryRefundedTotal: number | null = null
  if (!isDepositPaid(order.payment_status) && (paidByRazorpay || paidByOther)) {
    const charges = await getDeliveryCharges(supabase)
    let siblings: RefundOrderRow[] = [{
      id: order.id,
      farmer_id: order.farmer_id,
      status: order.status,
      delivery_fee: order.delivery_fee,
      delivery_fee_refunded: order.delivery_fee_refunded,
      payment_status: order.payment_status,
      razorpay_payment_id: order.razorpay_payment_id,
    }]
    if (order.checkout_id) {
      const { data: sibRows } = await supabase
        .from('orders').select(REFUND_ORDER_COLS).eq('checkout_id', order.checkout_id)
      if (sibRows && sibRows.length) siblings = sibRows as RefundOrderRow[]
    }
    deliveryPlan = planDeliveryRefund(siblings, order.id, charges)
    const cur = deliveryPlan.allocations.find((a) => a.orderId === order.id)
    currentDeliveryAmount = cur?.amount ?? 0
    currentDeliveryRefundedTotal = cur?.newRefundedTotal ?? null
  }

  // What we refund the buyer for THIS order: produce (fee withheld) + this
  // order's slice of the delivery drop.
  const refundAmount = produceRefund + currentDeliveryAmount

  // Part-paid COD: the deposit is forfeited when the BUYER cancels. That is the
  // entire reason it exists — on full COD a buyer could walk away from a
  // confirmed order having risked nothing, after the farmer had already
  // harvested for it. Refunding it here would make the deposit pointless.
  //
  // A farmer decline/cancel is the opposite case and DOES refund it in full —
  // see /api/farmer/orders/[id]/decline. Note deposit_paid is deliberately
  // absent from paidByRazorpay/paidByOther above, so no refund call is made.
  const depositForfeited = isDepositPaid(order.payment_status)
    ? Math.max(0, Number(order.cod_deposit) || 0)
    : 0
  if (depositForfeited > 0) {
    update.deposit_forfeited_at = new Date().toISOString()
    update.cod_balance_due = 0
  }

  if (paidByRazorpay) {
    const amountPaise = Math.round(refundAmount * 100)
    if (amountPaise > 0) {
      try {
        const refund = await refundPayment({
          paymentId: order.razorpay_payment_id as string,
          amountPaise,
          notes: { order_code: order.order_code ?? '', order_id: order.id, reason: 'buyer_cancel' },
        })
        update.refund_id = refund.id
        update.refund_status = refund.status ?? 'processed'
        update.refund_amount = Math.round(refund.amountPaise / 100)
        update.refunded_at = new Date().toISOString()
      } catch (e) {
        // The gateway refused the refund (e.g. account/gateway state). Don't
        // trap the buyer with an order they can't cancel: cancel it anyway and
        // flag the refund as failed, recording the amount owed so the team can
        // settle it manually from the Razorpay dashboard. The buyer sees a
        // "refund failed / will be processed manually" note.
        console.error('[YFF] razorpay refund on cancel failed:', e)
        update.refund_status = 'failed'
        update.refund_amount = refundAmount
      }
    }
  } else if (paidByOther) {
    update.refund_status = 'initiated'
    if (refundAmount > 0) update.refund_amount = Math.round(refundAmount)
  }
  // Record how much of this row's delivery fee has now been given back, so a
  // later sibling cancellation can't refund it twice.
  if (currentDeliveryRefundedTotal != null) update.delivery_fee_refunded = currentDeliveryRefundedTotal

  const { error: updErr } = await supabase.from('orders').update(update).eq('id', id)
  if (updErr) {
    console.error('[YFF] cancel update failed:', updErr.message)
    return NextResponse.json({ error: 'Could not cancel the order. Please try again.' }, { status: 500 })
  }

  // Settle any delivery refund that lands on SIBLING orders' payments (residual
  // base on an already-cancelled row). Best-effort: logged, never blocks cancel.
  if (deliveryPlan.allocations.some((a) => a.orderId !== order.id)) {
    await applySiblingDeliveryRefunds(supabase, deliveryPlan, order.id)
  }

  return NextResponse.json({
    ok: true,
    refunded: !!update.refund_id,
    refundInitiated: update.refund_status === 'initiated',
    refundFailed: update.refund_status === 'failed',
    refundAmount,
    // Of the refund, how much was the delivery charge (service not rendered).
    deliveryRefund: currentDeliveryAmount,
    platformFeeWithheld,
    // The buyer must be told plainly what the cancellation cost them.
    depositForfeited,
  })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getFarmerSessionFromRequest } from '@/lib/farmer-session'
import { refundPayment } from '@/lib/razorpay'
import { isDepositPaid } from '@/lib/payment'
import { getDeliveryCharges, planDeliveryRefund, type RefundOrderRow } from '@/lib/delivery-fee'
import { applySiblingDeliveryRefunds, REFUND_ORDER_COLS } from '@/lib/delivery-refund'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

// Farmer declines a pending order. This runs server-side (not in the
// dashboard) because issuing a real refund needs the Razorpay secret. Steps:
//   1. authorise the farmer and confirm the order is theirs and still pending
//   2. return the reserved stock
//   3. if the buyer paid by Razorpay, issue a real refund for the FULL amount
//      the buyer paid against this order — the produce price plus this row's
//      share of the delivery fee and platform fee (both stamped on the first
//      row of the cart). Because the farmer is the one cancelling, the buyer
//      should be made whole, not just refunded the produce. Other paid methods
//      get a manual 'initiated' marker carrying the same full amount.
//   4. mark the order declined
export async function POST(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const session = getFarmerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Please log in.' }, { status: 401 })

  const { id } = await ctx.params
  if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  const body = await req.json().catch(() => null)
  const reason = String((body as { reason?: unknown } | null)?.reason ?? '').trim().slice(0, 300)

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: order, error: loadErr } = await supabase
    .from('orders')
    .select('id, farmer_id, status, quantity, total_price, delivery_fee, delivery_fee_refunded, platform_fee, cod_deposit, produce_listing_id, harvest_id, payment_method, payment_status, razorpay_payment_id, checkout_id, order_code, shipped_at, collected_at, received_at')
    .eq('id', id)
    .maybeSingle()

  if (loadErr) return NextResponse.json({ error: loadErr.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.farmer_id !== session.farmerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }
  // A farmer can decline/cancel an order while it is still pending OR approved
  // but not yet fulfilled — the OrderCard offers Decline in both states (e.g.
  // the crop is damaged after the farmer already approved). Once it has been
  // shipped, picked up or received it's too late. Rejecting anything already
  // declined/cancelled also keeps a double-tap from refunding twice.
  if (order.status !== 'pending' && order.status !== 'approved') {
    return NextResponse.json({ error: 'This order can no longer be declined.' }, { status: 409 })
  }
  if (order.shipped_at || order.collected_at || order.received_at) {
    return NextResponse.json(
      { error: 'This order has already been fulfilled and can no longer be declined.' },
      { status: 409 },
    )
  }

  // 1. Return the reserved stock. Harvest orders return the harvest's stock;
  // legacy orders the listing's.
  if (order.quantity != null && order.quantity > 0) {
    try {
      if (order.harvest_id) {
        await supabase.rpc('increment_harvest_stock', { p_harvest_id: order.harvest_id, p_qty: order.quantity })
      } else if (order.produce_listing_id) {
        await supabase.rpc('increment_stock', { p_listing_id: order.produce_listing_id, p_qty: order.quantity })
      }
    } catch (e) {
      console.error('[YFF] restock on decline failed:', e)
    }
  }

  // 2. Refund if the buyer actually paid.
  const update: Record<string, unknown> = { status: 'declined', decline_reason: reason || null }

  // A part-paid COD order carries 'deposit_paid', not 'paid' — but the deposit
  // was a real Razorpay capture and this is the farmer's decision, not the
  // buyer's, so it must be refunded in full. (A BUYER cancel forfeits it
  // instead; that asymmetry is the whole point of the deposit.) Without this,
  // declining would silently keep the buyer's money.
  const depositPaid = isDepositPaid(order.payment_status)
  const paidByRazorpay =
    (order.payment_status === 'paid' || depositPaid) && !!order.razorpay_payment_id
  const paidByOther =
    order.payment_status === 'completed' ||
    order.payment_status === 'payment_claimed' ||
    order.payment_status === 'pending_confirmation'

  // The non-delivery amount the buyer paid against THIS order row.
  //
  // Part-paid COD: only the deposit ever reached us — the balance (which is
  // where most of the delivery charge sits) was cash the rider never collected,
  // so the deposit is the whole of what we can give back and delivery is not
  // coordinated separately below.
  //
  // Otherwise: the produce price plus this row's platform fee. The delivery
  // charge is handled by planDeliveryRefund, because when the farmer drops out
  // of a multi-farmer checkout the charge only falls by ONE farmer's worth, not
  // this whole row's stamped fee — and any base still owed may sit on a sibling.
  const itemPlatformRefund = depositPaid
    ? Math.max(0, Number(order.cod_deposit) || 0)
    : (Number(order.total_price) || 0) + (Number(order.platform_fee) || 0)

  // Work out the delivery-charge refund across the whole checkout (pure — no
  // writes yet). Skipped for the deposit path (delivery there was cash/in-deposit)
  // and when nothing was captured.
  let deliveryPlan: ReturnType<typeof planDeliveryRefund> = { owed: 0, allocations: [] }
  let currentDeliveryAmount = 0
  let currentDeliveryRefundedTotal: number | null = null
  if (!depositPaid && (paidByRazorpay || paidByOther)) {
    const charges = await getDeliveryCharges(supabase)
    let siblings: RefundOrderRow[] = [{
      id: order.id,
      farmer_id: order.farmer_id,
      status: order.status,
      delivery_fee: order.delivery_fee,
      delivery_fee_refunded: order.delivery_fee_refunded,
      payment_status: order.payment_status,
      razorpay_payment_id: order.razorpay_payment_id,
    }]
    if (order.checkout_id) {
      const { data: sibRows } = await supabase
        .from('orders').select(REFUND_ORDER_COLS).eq('checkout_id', order.checkout_id)
      if (sibRows && sibRows.length) siblings = sibRows as RefundOrderRow[]
    }
    deliveryPlan = planDeliveryRefund(siblings, order.id, charges)
    const cur = deliveryPlan.allocations.find((a) => a.orderId === order.id)
    currentDeliveryAmount = cur?.amount ?? 0
    currentDeliveryRefundedTotal = cur?.newRefundedTotal ?? null
  }

  // Refund the buyer for THIS order: produce + platform + this order's own slice
  // of the delivery drop, in one gateway call.
  const currentRefund = itemPlatformRefund + currentDeliveryAmount

  if (paidByRazorpay) {
    const amountPaise = Math.round(currentRefund * 100)
    if (amountPaise > 0) {
      try {
        const refund = await refundPayment({
          paymentId: order.razorpay_payment_id as string,
          amountPaise,
          notes: { order_code: order.order_code ?? '', order_id: order.id },
        })
        update.refund_id = refund.id
        update.refund_status = refund.status ?? 'processed'
        update.refund_amount = Math.round(refund.amountPaise / 100)
        update.refunded_at = new Date().toISOString()
      } catch (e) {
        // Refund failed at Razorpay. Don't silently swallow it — keep the
        // order pending so the farmer can retry, and surface the error. We have
        // not touched any sibling yet, so nothing is left half-done.
        console.error('[YFF] razorpay refund failed:', e)
        return NextResponse.json(
          { error: 'Could not issue the refund. The order was not declined — please try again.' },
          { status: 502 },
        )
      }
    }
  } else if (paidByOther) {
    // Non-Razorpay paid (UPI/manual): flag for manual refund, recording the
    // amount owed so whoever settles it knows the figure.
    update.refund_status = 'initiated'
    if (currentRefund > 0) update.refund_amount = Math.round(currentRefund)
  }
  // Record how much of this row's delivery fee has now been given back, so a
  // later sibling cancellation can't refund it twice.
  if (currentDeliveryRefundedTotal != null) update.delivery_fee_refunded = currentDeliveryRefundedTotal

  const { error: updErr } = await supabase.from('orders').update(update).eq('id', id)
  if (updErr) {
    console.error('[YFF] decline update failed:', updErr.message)
    return NextResponse.json({ error: 'Could not decline the order. Please try again.' }, { status: 500 })
  }

  // The buyer's own refund is done and the order is declined. Now settle any
  // delivery refund that lands on SIBLING orders' payments (e.g. residual base
  // on an already-cancelled row). Best-effort: logged, never blocks the decline.
  if (deliveryPlan.allocations.some((a) => a.orderId !== order.id)) {
    await applySiblingDeliveryRefunds(supabase, deliveryPlan, order.id)
  }

  return NextResponse.json({
    ok: true,
    refunded: !!update.refund_id,
    refundStatus: (update.refund_status as string | undefined) ?? null,
    // The actual amount refunded to the buyer (full: produce + delivery +
    // platform fee), so the confirmation screen shows the real figure rather
    // than the produce price alone.
    refundAmount: typeof update.refund_amount === 'number' ? update.refund_amount : null,
  })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

export async function GET(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Login required.' }, { status: 401 })

  const { id } = await ctx.params
  if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: order, error } = await supabase
    .from('orders')
    .select(
      'id, order_code, consumer_id, produce_name, produce_listing_id, quantity, unit, total_price, platform_fee, delivery_fee, delivery_fee_refunded, pickup_location, status, payment_method, payment_method_detail, payment_status, paid_at, confirmed_at, razorpay_payment_id, refund_status, refund_id, refund_amount, refunded_at, decline_reason, payment_proof_path, created_at, farmer_id, delivery_type, delivery_status, delivery_address, delivery_city, delivery_landmark, delivery_pincode, delivery_alt_phone, delivery_boy_id, handover_otp, assigned_at, picked_up_at, out_for_delivery_at, delivered_at, collected_at, shipped_at, received_at, fulfillment_date',
    )
    .eq('id', id)
    .maybeSingle()

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.consumer_id !== session.consumerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }

  // Manual farmer join (no FK on orders.farmer_id → farmers.id, so embedding fails)
  let farmer: { name: string; slug: string; village: string; phone: string | null; upi_id: string | null } | null = null
  if (order.farmer_id) {
    const { data: f } = await supabase
      .from('farmers')
      .select('id, name, slug, village, phone, upi_id')
      .eq('id', order.farmer_id)
      .maybeSingle()
    if (f) {
      farmer = {
        name: f.name,
        slug: f.slug,
        village: f.village,
        phone: f.phone ?? null,
        upi_id: (f.upi_id as string | null) ?? null,
      }
    }
  }

  // Rider contact (only after a rider has been assigned). Minimal exposure:
  // name + phone, nothing else.
  let rider: { id: string; name: string | null; phone: string } | null = null
  const dbi = (order as { delivery_boy_id?: string | null }).delivery_boy_id ?? null
  if (dbi) {
    const { data: r } = await supabase
      .from('delivery_boys')
      .select('id, name, phone')
      .eq('id', dbi)
      .maybeSingle()
    if (r) rider = { id: r.id, name: r.name ?? null, phone: r.phone }
  }

  // The buyer's own produce review for this order, if they've left one. Drives
  // the "Rate this produce" box on the order detail page.
  let myReview: { id: string; star_rating: number; review_text: string | null; created_at: string } | null = null
  const { data: rev } = await supabase
    .from('produce_reviews')
    .select('id, star_rating, review_text, created_at')
    .eq('order_id', order.id)
    .maybeSingle()
  if (rev) myReview = rev

  // Reschedule note (the reason the farmer gave when moving the pickup/delivery
  // date after approval). Fetched separately and tolerantly: the columns may not
  // exist until scripts/reschedule-reason-migration.sql is applied, and a
  // missing column must never break the order page.
  let reschedule: { reschedule_reason: string | null; rescheduled_at: string | null } = {
    reschedule_reason: null, rescheduled_at: null,
  }
  const { data: rs } = await supabase
    .from('orders')
    .select('reschedule_reason, rescheduled_at')
    .eq('id', order.id)
    .maybeSingle()
  if (rs) reschedule = rs as typeof reschedule

  return NextResponse.json({ order: { ...order, ...reschedule, farmer, rider, my_review: myReview } })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getFarmerSessionFromRequest } from '@/lib/farmer-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

// Farmer acknowledges a buyer-cancelled order. When a consumer cancels, the
// order would otherwise drop straight into history and the farmer would never
// notice. Instead it stays in the farmer's active list with an "Acknowledge"
// button; tapping it stamps acknowledged_at, which resolves the order and moves
// it to Order History. Mirror of the consumer-side acknowledge for declines.
export async function POST(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const session = getFarmerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Please log in.' }, { status: 401 })

  const { id } = await ctx.params
  if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: order, error: loadErr } = await supabase
    .from('orders')
    .select('id, farmer_id, status, acknowledged_at')
    .eq('id', id)
    .maybeSingle()

  if (loadErr) return NextResponse.json({ error: loadErr.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.farmer_id !== session.farmerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }
  // Only a buyer-cancelled order needs the farmer's acknowledgement.
  if (order.status !== 'cancelled') {
    return NextResponse.json({ error: 'This order does not need acknowledgement.' }, { status: 409 })
  }
  // Idempotent: already acknowledged is a no-op success.
  if (order.acknowledged_at) return NextResponse.json({ ok: true, acknowledged_at: order.acknowledged_at })

  const { data: updated, error: updErr } = await supabase
    .from('orders')
    .update({ acknowledged_at: new Date().toISOString() })
    .eq('id', id)
    .eq('farmer_id', session.farmerId)
    .eq('status', 'cancelled')
    .select('id, acknowledged_at')

  if (updErr) {
    console.error('[YFF farmer/acknowledge] update failed:', updErr.message)
    return NextResponse.json({ error: 'Could not update. Please try again.' }, { status: 500 })
  }
  if (!updated || updated.length === 0) {
    return NextResponse.json({ error: 'Could not update. Refresh and try again.' }, { status: 409 })
  }

  return NextResponse.json({ ok: true, acknowledged_at: updated[0].acknowledged_at })
}

