        onClick={() => onUpdatePaymentStatus('pending')}
        disabled={processingPaid}
        className="border-2 border-amber-300 text-amber-700 font-bold py-2.5 rounded-xl text-xs disabled:opacity-50 active:bg-amber-50"
      >
        {L('⏳ Pending', 'పెండింగ్')}
      </button>
    </div>
  </div>
)}

